import os
import signal

def terminate_process(pid, sig):
    # Check if PID is valid and a number
    if not isinstance(pid, int) or pid <= 0:
        raise ValueError("Invalid PID.")

    # Check if signal is valid
    if not isinstance(sig, int) or sig <= 0 or sig >= signal.NSIG:
        raise ValueError("Invalid signal.")

    # Check if the process exists and is accessible
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        raise ProcessLookupError("No such process.")

    # Ensure correct permissions
    if os.geteuid() != 0:
        # Get information about the process
        try:
            proc_stat = os.stat(f"/proc/{pid}")
        except FileNotFoundError:
            raise ProcessLookupError("No such process.")

        # Check ownership to ensure permission
        if os.getuid() != proc_stat.st_uid:
            raise PermissionError("Insufficient permissions to terminate the process.")

    # Attempt to send the signal
    try:
        os.kill(pid, sig)
    except PermissionError:
        raise PermissionError("Failed to send signal due to permission error.")
    except ProcessLookupError:
        raise ProcessLookupError("Process does not exist.")

