import base64
import json

class AuthFail(Exception):
    pass

def confirm_auth(headers, check_hmac, get_secret_key):
    auth_token = headers.get('AuthToken', None)

    if not auth_token:
        raise AuthFail("Missing AuthToken")

    try:
        # Ensure correct base64 padding
        missing_padding = len(auth_token) % 4
        if missing_padding:
            auth_token += '=' * (4 - missing_padding)
        # Decode base64 and parse JSON
        decoded_token = base64.urlsafe_b64decode(auth_token).decode('utf-8')
        token_data = json.loads(decoded_token)
    except (ValueError, json.JSONDecodeError, base64.binascii.Error):
        raise AuthFail("Invalid token format")

    signature = token_data.get('signature')
    data = token_data.get('data')

    if not signature or not data:
        raise AuthFail("Invalid token structure")

    secret_key = get_secret_key()

    if not check_hmac(signature, data, secret_key):
        raise AuthFail("Invalid HMAC")

    return data

