def create_user_directory(username, is_invalid_username, raise_privileges, lower_privileges):
    # Check if the username is invalid
    if is_invalid_username(username):
        return False

    try:
        # Attempt to raise privileges
        raise_privileges()

        try:
            # Create the user directory
            user_dir = Path(f"/home/{username}")
            user_dir.mkdir(parents=True, exist_ok=True)

        except Exception:
            # Return False if any error occurs during directory creation
            return False

        # Ensure privileges are lowered after directory operation
        finally:
            try:
                # Attempt to lower privileges
                lower_privileges()
            except Exception:
                # Return False if lowering privileges fails
                return False

        # Return True if user directory was successfully created
        return True

    except Exception:
        # Ensure privileges are lowered if raising privileges fails
        try:
            lower_privileges()
        except Exception:
            pass
        # Return False if raising privileges or lowering in finally fails
        return False

