        'encoding',
        'gzip\r\nContent-Type: text/html',
        None,
        'security',
        marks=pytest.mark.security,
    ),
    pytest.param(
        'cache', f'max-age=0'*1000, None, 'security', marks=pytest.mark.security
    ),
]


