    pytest.param(
        '<script>alert("XSS")</script>',
        f'Welcome, {html.escape("<script>alert(`XSS`)</script>")}!',
        'security',
        marks=pytest.mark.security,
    ),
    pytest.param(
        '<div attr=”*x” onblur=”alert(1)*”>',
